from pathlib import Path
import json,copy,hashlib,datetime,random
R=Path(__file__).resolve().parents[1];P=R/'data/question-batches/W08-L40.json';b=json.loads(P.read_text());old=copy.deepcopy(b);by={q['id']:q for q in b['questions']};rev=json.loads((R/'data/reviews/W08-L40-v1-independent.json').read_text());accepted={x['questionId']for x in rev if x['decision']=='verified'};flags={x['questionId']for x in rev if x['decision']=='flagged'};changed=set()
assert len(accepted)==33 and len(flags)==22

def edit(n,stem=None,correct=None,wrong=None,why=None):
 q=by[f'W08-L40-Q{n:03d}'];assert q['id']in flags
 if q['id']not in changed:q['version']+=1;q['status']='draft';q['reviewIds']=[];q['authorId']='build_robotics_study_app:L40-repair';changed.add(q['id'])
 if stem:q['stem']=stem
 if correct:
  key=q['correctOptionIds'][0];bad=[o['id']for o in q['options']if o['id']!=key];assert len(wrong)==3
  for o in q['options']:o['text']=correct if o['id']==key else wrong[bad.index(o['id'])][0]
  q['solution']['optionExplanations']={key:why or q['solution']['justification'],**{k:x[1]for k,x in zip(bad,wrong)}}
  q['solution']['misconceptions']=[x[1]for x in wrong]
 if why:q['solution']['justification']=q['solution']['simpleExplanation']=why
 return q
